mapper.select:
SELECT site_id, site_name, site_url, status, is_default
FROM cms_site
WHERE site_id = #{siteId}

SELECT EXISTS ( SELECT 1 FROM cms_site WHERE LOWER(BTRIM(site_url)) = LOWER(#{siteUrl}) AND site_url <> ''
AND site_id <> #{excludeSiteId}
)

mapper.update:
UPDATE cms_site
SET status = #{status}, updated_at = CURRENT_TIMESTAMP
WHERE site_id = #{siteId}

UPDATE cms_site
SET is_default = TRUE, updated_at = CURRENT_TIMESTAMP
WHERE site_id = #{siteId}

mapper.select:
SELECT COUNT(*)
FROM cms_page
WHERE site_id = #{siteId}

SELECT COUNT(*)
FROM cms_post
WHERE site_id = #{siteId}

SELECT COUNT(*)
FROM cms_media
WHERE site_id = #{siteId}
